create table public.jz_books (id uuid primary key default gen_random_uuid(), name text not null check (char_length(name) between 1 and 40), owner_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table public.jz_members (book_id uuid not null references public.jz_books on delete cascade, user_id uuid not null references auth.users on delete cascade, joined_at timestamptz not null default now(), primary key (book_id,user_id));
create table public.jz_invites (id uuid primary key default gen_random_uuid(), book_id uuid not null references public.jz_books on delete cascade, token uuid not null unique default gen_random_uuid(), expires_at timestamptz not null default now() + interval '7 days', used_at timestamptz, created_at timestamptz not null default now());
create table public.jz_transactions (id uuid primary key default gen_random_uuid(), book_id uuid not null references public.jz_books on delete cascade, user_id uuid not null references auth.users on delete cascade, kind text not null check (kind in ('expense','income')), amount integer not null check (amount > 0), category text not null check (char_length(category) between 1 and 30), note text not null default '' check (char_length(note) <= 200), occurred_on date not null, created_at timestamptz not null default now());
create index jz_transactions_book_date on public.jz_transactions(book_id, occurred_on desc);
create table public.jz_budgets (book_id uuid not null references public.jz_books on delete cascade, month date not null check (extract(day from month) = 1), amount integer not null check (amount >= 0), primary key(book_id, month));
create schema if not exists jz_private;
revoke all on schema jz_private from public;
grant usage on schema jz_private to authenticated;
create function jz_private.is_member(book uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.jz_members where book_id = book and user_id = (select auth.uid())) $$;
revoke all on function jz_private.is_member(uuid) from public;
grant execute on function jz_private.is_member(uuid) to authenticated;
alter table public.jz_books enable row level security;
alter table public.jz_members enable row level security;
alter table public.jz_invites enable row level security;
alter table public.jz_transactions enable row level security;
alter table public.jz_budgets enable row level security;
grant select on public.jz_books, public.jz_members to authenticated;
grant select, insert, update, delete on public.jz_transactions, public.jz_budgets to authenticated;
create policy books_read on public.jz_books for select to authenticated using (jz_private.is_member(id));
create policy members_read on public.jz_members for select to authenticated using (jz_private.is_member(book_id));
create policy transactions_read on public.jz_transactions for select to authenticated using (jz_private.is_member(book_id));
create policy transactions_insert on public.jz_transactions for insert to authenticated with check (jz_private.is_member(book_id) and user_id = (select auth.uid()));
create policy transactions_update on public.jz_transactions for update to authenticated using (jz_private.is_member(book_id)) with check (jz_private.is_member(book_id));
create policy transactions_delete on public.jz_transactions for delete to authenticated using (jz_private.is_member(book_id));
create policy budgets_access on public.jz_budgets for all to authenticated using (jz_private.is_member(book_id)) with check (jz_private.is_member(book_id));
create function public.jz_create_book(book_name text) returns uuid language plpgsql security definer set search_path = '' as $$ declare new_id uuid; begin if auth.uid() is null then raise exception 'Sign in required'; end if; insert into public.jz_books(name,owner_id) values(trim(book_name),auth.uid()) returning id into new_id; insert into public.jz_members(book_id,user_id) values(new_id,auth.uid()); return new_id; end $$;
create function public.jz_create_invite(book uuid) returns uuid language plpgsql security definer set search_path = '' as $$ declare new_token uuid; begin if not exists(select 1 from public.jz_books where id=book and owner_id=auth.uid()) then raise exception 'Only the owner can invite'; end if; insert into public.jz_invites(book_id) values(book) returning token into new_token; return new_token; end $$;
create function public.jz_join_book(invite_token uuid) returns uuid language plpgsql security definer set search_path = '' as $$ declare target uuid; begin if auth.uid() is null then raise exception 'Sign in required'; end if; update public.jz_invites set used_at=now() where token=invite_token and used_at is null and expires_at > now() returning book_id into target; if target is null then raise exception 'Invite invalid or expired'; end if; insert into public.jz_members(book_id,user_id) values(target,auth.uid()) on conflict do nothing; return target; end $$;
revoke all on function public.jz_create_book(text), public.jz_create_invite(uuid), public.jz_join_book(uuid) from public;
grant execute on function public.jz_create_book(text), public.jz_create_invite(uuid), public.jz_join_book(uuid) to authenticated;

revoke execute on function public.jz_create_book(text), public.jz_create_invite(uuid), public.jz_join_book(uuid) from anon;
